/**
 * Config plugin: enable Android `dataBinding` in the app module.
 *
 * WHY THIS EXISTS
 * `react-native-moyasar-sdk` ships Android views built with data binding, and
 * its installation guide requires the consuming app to turn the feature on:
 *
 *   android { buildFeatures { dataBinding true } }
 *
 * Without it the app compiles until the payment screen is reached, then fails
 * to link the SDK's generated binding classes.
 *
 * WHY A PLUGIN AND NOT A HAND EDIT
 * `android/` is gitignored and regenerated by every `expo prebuild`, so editing
 * `app/build.gradle` directly reverts silently — and the failure surfaces later
 * as an unexplained build error with no trace of what removed the setting.
 * Config plugins run as part of prebuild, so the change is reapplied every time.
 * Same reasoning as plugins/withAndroidAbiFilters.js.
 */
const { withAppBuildGradle } = require('expo/config-plugins');

/** Matches an existing `buildFeatures { … }` block inside the app module. */
const BUILD_FEATURES_RE = /buildFeatures\s*\{/;
/** The `android {` opening we anchor to when no buildFeatures block exists. */
const ANDROID_RE = /^android\s*\{/m;

const withAndroidDataBinding = (config) =>
  withAppBuildGradle(config, (cfg) => {
    let src = cfg.modResults.contents;

    // Already enabled (by the template, another plugin, or a previous run).
    if (/dataBinding\s+true/.test(src)) return cfg;

    if (BUILD_FEATURES_RE.test(src)) {
      // Extend the block that is already there rather than adding a second one;
      // Gradle accepts duplicates but they make the file confusing to read.
      src = src.replace(BUILD_FEATURES_RE, 'buildFeatures {\n        dataBinding true');
    } else if (ANDROID_RE.test(src)) {
      src = src.replace(
        ANDROID_RE,
        'android {\n    // Set by plugins/withAndroidDataBinding.js — required by react-native-moyasar-sdk.\n    buildFeatures {\n        dataBinding true\n    }',
      );
    } else {
      // No `android {` block is not something we can paper over: the file is
      // not what we think it is, and silently returning would produce an APK
      // that fails at the payment screen.
      throw new Error(
        'withAndroidDataBinding: no `android {` block in app/build.gradle — cannot enable dataBinding.',
      );
    }

    cfg.modResults.contents = src;
    return cfg;
  });

module.exports = withAndroidDataBinding;
